<?phpif (!defined('BASEPATH')) {	exit('No direct script access allowed');}include_once APPPATH . '/modules/layout/controllers/Layout.php';class Provider extends Layout {	private $_module_slug = 'nha-cung-cap';	private $_module_name = 'nhà cung cấp';	function __construct() {		parent::__construct();		$this->load->model('provider/m_provider', 'M_provider');		$this->_data['breadcrumbs_module_name'] = ucfirst($this->_module_name);		$this->_data['breadcrumbs_module_func'] = 'Danh sách';		$this->_data['module_slug'] = $this->_module_slug;		$this->_data['module_name'] = $this->_module_name;		$_breadcrumbs_admin[] = array(			'url' => '',			'name' => 'Nhà cung cấp',			'image' => base_url('assets/Frest/app-assets/images/svg/ico/ico-provider.svg'),		);		$this->_data['breadcrumbs_admin'] = $_breadcrumbs_admin;	}	private function _validate_access_role(){		$this->validate_access_role('ROLE_GROUP_PROVIDER');	}	function default_args() {		$order_by = array(			'order' => 'ASC',			'modified' => 'DESC',			'name' => 'ASC',		);		$args = array();		$args['order_by'] = $order_by;		return $args;	}	function counts($args) {		return $this->M_provider->counts($args);	}	function get($id) {		return $this->M_provider->get($id);	}	function get_max_order() {		$args = $this->default_args();		$order_by = array(			'order' => 'DESC',		);		$args['order_by'] = $order_by;		$perpage = 1;		$offset = 0;		$rows = $this->M_provider->gets($args, $perpage, $offset);		$max_order = isset($rows[0]['order']) ? $rows[0]['order'] : 0;		return (int) $max_order;	}	function gets($in_id = array()) {		$this->load->model('m_provider', 'M_provider');		$args = $this->default_args();		if (is_array($in_id) && !empty($in_id)) {			$args = array();			$args['in_id'] = $in_id;		}		return $this->M_provider->gets($args);	}	function gets_in_id() {		$this->load->model('m_provider', 'M_provider');		$args = $this->default_args();		return $this->M_provider->gets($args);	}	function admin_view() {		$this->_initialize_admin();		$this->_validate_access_role();		$id = (int) (($this->uri->segment(3) == '') ? 0 : $this->uri->segment(3));		if ($id == 0) {			show_404();		}		$this->_data['current_page'] = (int) $this->input->get('current_page');		$row = $this->get($id);		$this->_data['row'] = $row;		$this->_data['breadcrumbs_module_func'] = 'Xem thông tin nhà cung cấp';				$this->_data['supplier_type'] = modules::run('provider/supplier_type/gets');		$this->_data['title'] = 'Xem thông tin nhà cung cấp - ' . $this->_data['breadcrumbs_module_name'];		$this->_data['main_content'] = 'admin/view_page_view';		$this->load->view('layout/admin/view_layout', $this->_data);	}	function admin_report_export_excel() {		$this->_initialize_admin();		$this->_validate_access_role();		$this->load->model('purchase_voucher/m_purchase_voucher_details', 'M_purchase_voucher_details');		$args = $this->default_args();		$rows = $this->M_provider->gets($args);		if (!is_array($rows) && empty($rows)) {			$this->_module_slug = 'bao-cao/nha-cung-cap';			$notify_type = 'danger';			$notify_content = 'Chưa có dữ liệu!';			$this->set_notify_admin($notify_type, $notify_content);			redirect(base_url($this->_module_slug));		}		$this->load->library('excel');		$styleAlignmentCenter = array(			'horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_CENTER,		);		$styleAlignmentRight = array(			'horizontal' => PHPExcel_Style_Alignment::HORIZONTAL_RIGHT,		);		$styleHeader = array(			'name' => 'Arial',			'bold' => true,			'color' => array(				'rgb' => 'FFFFFF',			),		);		$styleHighlight = array(			'font' => array(				'bold' => true,				'color' => array('rgb' => '3582F4'),			),		);		$this->excel->getProperties()->setCreator("Admin")			->setLastModifiedBy("Admin")			->setTitle("Báo cáo theo nhà cung cấp")			->setSubject("Báo cáo theo nhà cung cấp")			->setDescription("Báo cáo theo nhà cung cấp")			->setKeywords("Báo cáo theo nhà cung cấp")			->setCategory("Báo cáo theo nhà cung cấp");		$this->excel->getActiveSheet()->setTitle('Báo cáo theo nhà cung cấp');		$this->excel->setActiveSheetIndex(0)			->setCellValue('A1', 'STT')			->setCellValue('B1', 'Tên nhà cung cấp')			->setCellValue('C1', 'Tổng tiền');		$this->excel->getActiveSheet()->getStyle("A1:C1")->getFont()->setBold(true);		$this->excel->getActiveSheet()->getStyle('A1:C1')->getFill()->setFillType(PHPExcel_Style_Fill::FILL_SOLID);		$this->excel->getActiveSheet()->getStyle('A1:C1')->getFill()->getStartColor()->setARGB('FF0000');		// Add some data		$this->excel->getActiveSheet()->getStyle("A1:C1")->getFont()->setBold(true);		$this->excel->getActiveSheet()->getStyle('A1:C1')->getBorders()->getAllBorders()->setBorderStyle(PHPExcel_Style_Border::BORDER_THIN);		//Header		$this->excel->getActiveSheet()->getStyle('A1:C1')->getFont()->applyFromArray($styleHeader);		//Alignment		$this->excel->getActiveSheet()->getStyle('A1')->getAlignment()->applyFromArray($styleAlignmentCenter);		$this->excel->getActiveSheet()->getStyle('C1')->getAlignment()->applyFromArray($styleAlignmentRight);		$this->excel->getActiveSheet()->getColumnDimension('A')->setAutoSize(true);		$this->excel->getActiveSheet()->getColumnDimension('B')->setAutoSize(true);		$this->excel->getActiveSheet()->getColumnDimension('C')->setAutoSize(true);		$i = 2;		$order = 0;		$total_number = 0;		foreach ($rows as $row) {			$args = array(				'provider_id' => $row['id'],			);			$purchase_voucher_details = $this->M_purchase_voucher_details->gets($args);			$total_number_monetized = (is_array($purchase_voucher_details) && !empty($purchase_voucher_details)) ? array_sum(array_column($purchase_voucher_details, 'monetized')) : 0;			$total_number += $total_number_monetized;			$this->excel->getActiveSheet()->getStyle('A' . $i . '')->getBorders()->getAllBorders()->setBorderStyle(PHPExcel_Style_Border::BORDER_THIN);			$this->excel->getActiveSheet()->getStyle('B' . $i . '')->getBorders()->getAllBorders()->setBorderStyle(PHPExcel_Style_Border::BORDER_THIN);			$this->excel->getActiveSheet()->getStyle('C' . $i . '')->getBorders()->getAllBorders()->setBorderStyle(PHPExcel_Style_Border::BORDER_THIN);			$order++;			$this->excel->setActiveSheetIndex(0)				->setCellValue('A' . $i, $order)				->setCellValue('B' . $i, $row['name'])				->setCellValue('C' . $i, format_rice_en($total_number_monetized));			//Highlight			$this->excel->getActiveSheet()->getStyle('B' . $i)->applyFromArray($styleHighlight);			$this->excel->getActiveSheet()->getStyle('C' . $i)->applyFromArray($styleHighlight);			//Alignment			$this->excel->getActiveSheet()->getStyle('A' . $i)->getAlignment()->applyFromArray($styleAlignmentRight);			$this->excel->getActiveSheet()->getStyle('C' . $i)->getAlignment()->applyFromArray($styleAlignmentRight);			$i++;		}		$this->excel->getActiveSheet()->getStyle('A' . $i . '')->getBorders()->getAllBorders()->setBorderStyle(PHPExcel_Style_Border::BORDER_THIN);		$this->excel->getActiveSheet()->getStyle('B' . $i . '')->getBorders()->getAllBorders()->setBorderStyle(PHPExcel_Style_Border::BORDER_THIN);		$this->excel->getActiveSheet()->getStyle('C' . $i . '')->getBorders()->getAllBorders()->setBorderStyle(PHPExcel_Style_Border::BORDER_THIN);		$this->excel->setActiveSheetIndex(0)			->setCellValue('A' . $i, 'Tổng cộng')			->setCellValue('C' . $i, format_rice_en($total_number));		$this->excel->setActiveSheetIndex(0)->mergeCells('A' . $i . ':' . 'B' . $i);		//Total		$styleTotal = array(			'font' => array(				'bold' => true,				'color' => array('rgb' => 'FF0000'),			),		);		$this->excel->getActiveSheet()->getStyle('A' . $i)->applyFromArray($styleTotal);		$this->excel->getActiveSheet()->getStyle('C' . $i)->applyFromArray($styleTotal);		//Alignment		$this->excel->getActiveSheet()->getStyle('C' . $i)->getAlignment()->applyFromArray($styleAlignmentRight);		$filename = 'Bao-cao-theo-nha-cung-cap_' . date('Y-m-d_H-i-s') . '.xls';		header('Content-Type: application/vnd.ms-excel'); //mime type		header('Content-Disposition: attachment;filename="' . $filename . '"'); //tell browser what's the file name		header('Cache-Control: max-age=0');		$objWriter = PHPExcel_IOFactory::createWriter($this->excel, 'Excel5');		$objWriter->save('php://output');	}	function admin_report() {		$this->_initialize_admin();		$this->_validate_access_role();		$this->load->model('purchase_voucher/m_purchase_voucher_details', 'M_purchase_voucher_details');		$this->load->library('form_validation');		$this->_module_slug = 'bao-cao/nha-cung-cap';		$this->_data['module_slug'] = $this->_module_slug;		$_breadcrumbs_admin[] = array(			'url' => '',			'name' => 'Báo cáo ( nhà cung cấp )',			'image' => base_url('assets/Frest/app-assets/images/svg/ico/ico-report.svg'),		);		$this->_data['breadcrumbs_admin'] = $_breadcrumbs_admin;		$this->_plugins_css_admin[] = array(			'folder' => 'bootstrap-datepicker/css',			'name' => 'bootstrap-datepicker',		);		$this->_plugins_css_admin[] = array(			'folder' => 'bootstrap-datepicker/css',			'name' => 'bootstrap-datepicker3',		);		$this->_plugins_script_admin[] = array(			'folder' => 'bootstrap-datepicker/js',			'name' => 'bootstrap-datepicker',		);		$this->_plugins_script_admin[] = array(			'folder' => 'bootstrap-datepicker/locales',			'name' => 'bootstrap-datepicker.vi.min',		);		$this->_plugins_script_admin[] = array(			'folder' => 'jQuery-Plugin-To-Print-Any-Part-Of-Your-Page-Print',			'name' => 'jQuery.print',		);		$this->set_plugins_admin();		$this->_modules_script[] = array(			'folder' => 'provider',			'name' => 'admin-report',		);		$this->set_modules();		$get = $this->input->get();		$this->_data['get'] = $get;		$args = $this->default_args();		$provider = (int) (isset($get['provider']) ? $get['provider'] : 0);		if ($provider != 0) {			$args['in_id'] = $provider;		}		if(isset($get['fromday']) && trim($get['fromday']) != '' && isset($get['today']) && trim($get['today']) != ''){			$rows_provider = $this->M_purchase_voucher_details->gets(array(				'start_date_start' => get_start_date($get['fromday']),				'start_date_end' => get_end_date($get['today'])			));			if(is_array($rows_provider) && !empty($rows_provider)){				$in_id = array_unique(array_column($rows_provider, 'provider_id'));				$args['in_id'] = $in_id;			}else{				$args['in_id'] = array(-1);			}		}		$perpage = (int) (isset($get['per_page']) ? $get['per_page'] : 10);		if ($perpage === 0) {			$rows = $this->M_provider->gets($args);		} else {			$total = $this->counts($args);			$segment = 3;			$this->load->library('pagination');			$config['total_rows'] = $total;			$config['per_page'] = $perpage;			$config['full_tag_open'] = '<ul class="pagination no-margin pull-right">';			$config['full_tag_close'] = '</ul><!--pagination-->';			$config['first_link'] = '&laquo;';			$config['first_tag_open'] = '<li class="prev page">';			$config['first_tag_close'] = '</li>';			$config['last_link'] = '&raquo;';			$config['last_tag_open'] = '<li class="next page">';			$config['last_tag_close'] = '</li>';			$config['next_link'] = 'Trang trước &rarr;';			$config['next_tag_open'] = '<li class="next page">';			$config['next_tag_close'] = '</li>';			$config['prev_link'] = '&larr; Trang sau';			$config['prev_tag_open'] = '<li class="prev page">';			$config['prev_tag_close'] = '</li>';			$config['cur_tag_open'] = '<li class="active"><a href="">';			$config['cur_tag_close'] = '</a></li>';			$config['num_tag_open'] = '<li class="page">';			$config['num_tag_close'] = '</li>';			if (!empty($get)) {				$config['base_url'] = base_url($this->_module_slug);				$config['suffix'] = '?' . http_build_query($get, '', "&");				$config['first_url'] = base_url($this->_module_slug . '?' . http_build_query($get, '', "&"));				$config['uri_segment'] = $segment;			} else {				$config['base_url'] = base_url(